function buildMajorFactionCard(pack, item, cardType) {
  const typeLetter =
    cardType === 'creature'
      ? 'C'
      : cardType === 'tactic'
      ? 'T'
      : cardType === 'relic'
      ? 'R'
      : 'E';
  const id = `${pack.prefix}-${typeLetter}-${item.num}`;
  const effects = [];
  if (item.op) {
    const eff = { operation: item.op, target: item.target };
    if (item.amount !== undefined) eff.amount = item.amount;
    if (item.counter) eff.counter = item.counter;
    if (item.attack_delta !== undefined) eff.attack_delta = item.attack_delta;
    if (item.health_delta !== undefined) eff.health_delta = item.health_delta;
    if (item.keyword) eff.keyword = item.keyword;
    if (item.token_name) {
      eff.token_name = item.token_name;
      eff.attack = item.attack;
      eff.health = item.health;
      eff.keywords = item.keywords;
    }
    if (item.direction) eff.direction = item.direction;
    effects.push(eff);
  }
  if (item.op2) {
    effects.push(item.op2);
  }

  return {
    id,
    name: item.name,
    type: cardType,
    subtype: item.subtype,
    faction: pack.faction,
    rarity: item.rarity,
    role: cardType === 'creature' ? item.role : null,
    cost: item.cost,
    attack: cardType === 'creature' ? item.attack : 0,
    health: cardType === 'creature' ? item.health : 0,
    keywords: item.keywords || [],
    mechanics: [pack.mechanic],
    description: item.desc,
    abilities: [
      {
        trigger: item.trigger || (cardType === 'creature' ? 'on_summon' : 'on_play'),
        conditions: item.conditions || [],
        effects
      }
    ],
    lore: item.lore,
    archetypes: [`${pack.faction}_midrange`, `${pack.mechanic}_synergy`],
    weaknesses: ['silence', 'hard_removal'],
    complexity: item.rarity === 'common' ? 'beginner' : 'intermediate',
    art: {
      subject: item.subj,
      silhouette: item.sil,
      palette: pack.palette,
      lighting: pack.lighting,
      environment: pack.environment
    }
  };
}

