function buildNeutralCard(item) {
  const typeLetter =
    item.type === 'creature'
      ? 'C'
      : item.type === 'tactic'
      ? 'T'
      : item.type === 'relic'
      ? 'R'
      : 'E';
  const id = `NEU-${typeLetter}-${item.num}`;
  const effects = [];
  if (item.op) {
    const eff = { operation: item.op, target: item.target };
    if (item.amount !== undefined) eff.amount = item.amount;
    if (item.counter) eff.counter = item.counter;
    if (item.attack_delta !== undefined) eff.attack_delta = item.attack_delta;
    if (item.health_delta !== undefined) eff.health_delta = item.health_delta;
    if (item.keyword) eff.keyword = item.keyword;
    if (item.token_name) {
      eff.token_name = item.token_name;
      eff.attack = item.attack;
      eff.health = item.health;
      eff.keywords = item.keywords;
    }
    if (item.direction) eff.direction = item.direction;
    effects.push(eff);
  }
  if (item.op2) {
    effects.push(item.op2);
  }

  return {
    id,
    name: item.name.trim(),
    type: item.type,
    subtype: item.subtype,
    faction: 'neutral',
    rarity: item.rarity,
    role: item.type === 'creature' ? item.role : null,
    cost: item.cost,
    attack: item.type === 'creature' ? item.attack : 0,
    health: item.type === 'creature' ? item.health : 0,
    keywords: item.keywords || [],
    mechanics: [],
    description: item.desc,
    abilities: [
      {
        trigger: item.trigger || (item.type === 'creature' ? 'on_summon' : 'on_play'),
        conditions: item.conditions || [],
        effects
      }
    ],
    lore: item.lore,
    archetypes: ['neutral_versatility', 'lumenport_accord'],
    weaknesses: ['faction_synergy_outscaling'],
    complexity: item.rarity === 'common' ? 'beginner' : 'intermediate',
    art: {
      subject: item.subj,
      silhouette: item.sil,
      palette: ['warm_gold', 'sapphire_blue', 'limestone_cream'],
      lighting: 'Clear coastal Lumenport daylight with warm Aether accents',
      environment: 'Lumenport Free Harbor'
    }
  };
}

export const EXPANSION_320_CARDS = [];

for (const pack of MAJOR_FACTION_PACKS) {
  for (const c of pack.creatures) {
    EXPANSION_320_CARDS.push(buildMajorFactionCard(pack, c, 'creature'));
  }
  for (const t of pack.tactics) {
    EXPANSION_320_CARDS.push(buildMajorFactionCard(pack, t, 'tactic'));
  }
  for (const r of pack.relics) {
    EXPANSION_320_CARDS.push(buildMajorFactionCard(pack, r, 'relic'));
  }
  for (const e of pack.environments) {
    EXPANSION_320_CARDS.push(buildMajorFactionCard(pack, e, 'environment'));
  }
}

for (const item of NEUTRAL_48_ITEMS) {
  EXPANSION_320_CARDS.push(buildNeutralCard(item));
}

